package com.gymmind.nutrition.application; import com.gymmind.nutrition.domain.model.NutritionRecord; import java.time.LocalDate; public record NutritionRecordView(Long id,Long tenantId,Long memberId,LocalDate recordDate,double calories,double protein,double carbohydrate,double fat,String notes){public static NutritionRecordView from(NutritionRecord r){return new NutritionRecordView(r.getId(),r.getTenantId(),r.getMemberId(),r.getRecordDate(),r.getCalories(),r.getProtein(),r.getCarbohydrate(),r.getFat(),r.getNotes());}}
